16	/**
17	 * Resolves the EFFECTIVE registration date and rolls it onto a business day.
18	 *
19	 * <p>The effective date is the one supplied in the request, or the server's current date when the
20	 * request omits it. A supplied date later than the server's current date is rejected with 400 via
21	 * {@link MethodArgumentNotValidException} — an owner cannot be registered in the future. Otherwise,
22	 * when that date lands on a Saturday, Sunday or listed public holiday it is rolled forward to the
23	 * next non-holiday business day. The adjusted
24	 * date is published as a variable so every later step derives from the same value: the daily
25	 * create-limit counts owners per adjusted business day, {@link BuildOwner} stores it as the owner's
26	 * {@code registrationDate}, and {@link AssignMemberId} takes the member id's fiscal-year segment
27	 * from it.
28	 *
29	 * <p>Runs before {@link EnsureDailyOwnerLimit} so the limit is checked against the adjusted date.
30	 */
31	public class NormalizeRegistrationDate {
32	
33	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
34	        LocalDate.of(2026, 1, 1),
35	        LocalDate.of(2026, 1, 26),
36	        LocalDate.of(2026, 4, 25),
37	        LocalDate.of(2026, 12, 25),
38	        LocalDate.of(2026, 12, 28));
39	
40	    private static final Method SERVICE_METHOD;
41	
42	    static {
43	        try {
44	            SERVICE_METHOD = NormalizeRegistrationDate.class.getMethod("service", OwnerFieldsDto.class, Out.class);
45	        }
46	        catch (NoSuchMethodException ex) {
47	            throw new ExceptionInInitializerError(ex);
48	        }
49	    }
50	
51	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate)
52	            throws MethodArgumentNotValidException {
53	        LocalDate supplied = request.getRegistrationDate();
54	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
55	            BindingResult binding = new BeanPropertyBindingResult(request, "ownerFieldsDto");
56	            binding.rejectValue("registrationDate", "FutureDate",
57	                "registration date must not be later than the current date");
58	            throw new MethodArgumentNotValidException(new MethodParameter(SERVICE_METHOD, 0), binding);
59	        }
60	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
61	        registrationDate.set(toBusinessDay(effective));
62	    }
63	
64	    private static LocalDate toBusinessDay(LocalDate date) {
65	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
66	                || PUBLIC_HOLIDAYS.contains(date)) {
67	            date = date.plusDays(1);
68	        }
69	        return date;
70	    }
71	}
