54	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
55	    }
56	
57	    /** First 12 hex characters of SHA-256 over the 'V2' version tag, the normalized last name and the postcode. */
58	    private static String stableId(String lastName, String postcode) {
